import io,os,sys,base64,json
F=sys.argv[1] if len(sys.argv)>1 else "rep_gelisim_uret.mjs"
D=json.loads('[["c2lzdGVtaW4gb3Rvbm9tIGJ1bGd1bGFyaSAoc2lzdGVtX3NpbnlhbGxlcmkpLCBzb24gc2FoYSB6aXlhcmV0IG5vdGxhcmksIHRla2xpZiBrYXlpcCBuZWRlbmxlcmku", ""], ["ICAgIGNvbnN0IGJnID0gKGF3YWl0IHBvb2wucXVlcnkoIlNFTEVDVCByZXBfZ2VsaXNpbV9iYWdsYW0oJDE6OnV1aWQsJDI6OnV1aWQpIGIiLFtULHIudXNlcl9pZF0pKS5yb3dzWzBdLmI7", ""], ["K0pTT04uc3RyaW5naWZ5KGJnKS5zbGljZSgwLDE4MDAwKX1dIH0pOw==", "K0pTT04uc3RyaW5naWZ5KGJnKS5zbGljZSgwLDE4MDAwKSsnXG5cbllPTkVUSUNJIEdJUkRJU0kgKHllciBnZXJjZWdpIOKAlCBjaWthcmltZGFuIHVzdHVuKTpcbicrSlNPTi5zdHJpbmdpZnkoe25vdGxhcjpfeW4sdGVwa2lsZXI6X3l0fSkuc2xpY2UoMCw0MDAwKX1dIH0pOw=="]]')
s=io.open(F,encoding="utf-8").read()
if "IK_NOTU_BAGLAM_V1" in s:
    print("ZATEN VAR — IK_NOTU_BAGLAM_V1, atlandi"); sys.exit(0)
for o64,n64 in D:
    o=base64.b64decode(o64).decode(); n=base64.b64decode(n64).decode()
    if n in s and o not in s: continue
    c=s.count(o); assert c==1, "anchor=%d :: %s"%(c,o[:60])
    s=s.replace(o,n,1)
if not os.path.exists(F+".baglambak"):
    io.open(F+".baglambak","w",encoding="utf-8").write(io.open(F,encoding="utf-8").read())
io.open(F,"w",encoding="utf-8").write(s)
print("OK IK_NOTU_BAGLAM_V1 — rep_gelisim_uret.mjs guncellendi")
